Object.assign(SNIP,{});PRESET_NOTES["l26"]={"Ví dụ: Rẽ nhánh theo subtask": "Cặp có tổng chia hết cho 3: (1, 2), (1, 5), (2, 4), (4, 5) — 4 cặp. Với n nhỏ, nhánh trâu chạy; với n lớn, nhánh đếm số dư chạy. Hai nhánh độc lập: một nhánh sai không làm hỏng điểm của nhánh kia.", "Ví dụ: Ước lượng trước khi code": "Với ngưỡng khoảng 10⁸ phép tính mỗi giây: O(n²) kịp ở n = 1000 và n = 10⁴, không kịp ở n = 10⁵. Tính nhẩm như thế này cho từng dòng subtask trước khi viết code."};EX_HINTS["l26"]=[["Lời giải trâu O(n²) lấy được subtask 1.", "aᵢ + aⱼ chia hết cho k ⇔ (aᵢ mod k) + (aⱼ mod k) chia hết cho k. Đếm số dư của các số đứng trước bằng mảng cnt[k].", "Số dư bù của r là (k − r) mod k (với r = 0 thì bù là 0). Số cặp tới 5·10¹¹: long long."], ["Trâu O(n²) lấy subtask 1.", "Tổng đoạn (l, r] = p[r] − p[l] với l ≤ r − L. Với mỗi r, cần p[l] nhỏ nhất trong p[0 .. r − L].", "Giữ mn = min p[0 .. r − L] khi r tăng: O(n)."], ["Có số âm nên không dùng được hai con trỏ (Bài 16).", "Đoạn (l, r] có tổng S ⇔ p[l] = p[r] − S. Đếm số tiền tố trước đó bằng p[r] − S bằng map.", "Khởi tạo dem[0] = 1 (tiền tố rỗng). Kết quả tới n²/2: long long."]];
